  "diagnosis": "The candidate's retry_delay function fails when retry_after is None because it attempts to convert None to a float, which raises a TypeError. The function does not handle the case where retry_after is missing or invalid, and it does not clamp the delay to a non-negative value as required. The function should check if retry:after is a valid number before converting it, and ensure the result is non-negative.",
  "expected_effect": "The function should handle missing or invalid retry_after values by using the default, and ensure the result is non-negative and within the maximum limit.",
  "schema_version": "exp002-diagnosis-update/v1",
  "updates": {
    "harness.py": "def retry_delay(retry_after, default, maximum):
    """Return a bounded non-negative retry delay."""
    if retry_after is None or not isinstance(retry_after, (int, float)):
        return default
    try:
        delay = float(retry_after)
    except ValueError:
        return default
    return max(0, min(delay, maximum))"
  }
}

